.ds-index{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;display:grid;grid-template-columns:24px 1fr 20px;gap:15px;align-items:center;text-align:left;width:100%;border:0;border-bottom:1px solid #2b3039;background:#06070a;padding:18px 0;color:#f6f8fb;cursor:pointer;transition:background .18s}.ds-index:hover{background:#181c24}.ds-index strong{display:block;font-size:18px;font-weight:550;line-height:1.3}.ds-index small{display:block;color:#b6bcc7;margin-top:5px;font-size:13px} .ds-index:focus-visible{outline:3px solid #a4c4f0;outline-offset:4px} @media(prefers-reduced-motion:reduce){.ds-index{transition:none}} .ds-index .ds-index-price{color:#f6f8fb;margin-top:8px}.ds-index:focus-visible{outline-color:#a4c4f0} .ds-index strong{font-family:"Stratos Montserrat",Inter,sans-serif;font-size:17px;font-weight:550;line-height:1.45;letter-spacing:-.015em}

