.ds-cover{position:relative;isolation:isolate;background:linear-gradient(155deg,#091321 0%,#080d15 44%,#06070a 80%);color:#f6f8fb;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:48px 22px;overflow-wrap:anywhere}.ds-cover>p{color:#b6bcc7;font-size:13px}.ds-cover h1{margin:72px 0 0;font-size:clamp(48px,7.6vw,96px);font-weight:600;line-height:1.04;letter-spacing:-.035em;text-wrap:balance}.ds-cover h1 span{display:block;color:#b6bcc7;font-size:clamp(18px,2vw,24px);font-weight:400;line-height:1.4;letter-spacing:-.01em;margin-bottom:24px}.ds-cover .ds-cover-description{font-size:clamp(16px,1.5vw,19px);max-width:48ch;line-height:1.7;margin-top:30px}@media(max-width:760px){.ds-cover h1{font-size:clamp(42px,11vw,68px)}} .ds-cover::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(ellipse at 82% 18%,rgba(52,112,185,.25),rgba(28,65,112,.12) 38%,transparent 70%);animation:ds-cover-light 800ms cubic-bezier(.16,1,.3,1) both}@keyframes ds-cover-light{from{opacity:.35}to{opacity:1}}@media(max-width:760px){.ds-cover::before{background:radial-gradient(ellipse at 100% 24%,rgba(52,112,185,.28),rgba(28,65,112,.12) 44%,transparent 76%)}.ds-cover h1{line-height:1.08}.ds-cover .ds-cover-description{max-width:35ch}}@media(prefers-reduced-motion:reduce){.ds-cover::before{animation:none}} .ds-cover h1 span{font-family:"Stratos Montserrat",Inter,sans-serif;font-size:clamp(16px,1.6vw,21px);font-weight:500;letter-spacing:.015em;line-height:1.5}.ds-cover .ds-cover-description{line-height:1.75}

